if 'upper_names' not in globals():
    raise AssertionError('Task 1: upper_names variable not found')

upper_names = globals()['upper_names']

if not isinstance(upper_names, list):
    raise AssertionError('Task 1: upper_names should be a list (use list())')

expected = ['EDDARD', 'CATELYN', 'ROBB', 'SANSA', 'ARYA', 'BRANDON', 'RICKON']
if upper_names != expected:
    raise AssertionError(f'Task 1: Expected {expected}, got {upper_names}')

print('TEST_PASSED')

